package com.bank.merchtrie.trie;

import java.util.logging.Logger;

// Trie supporting insert, exact search, and prefix check.
public class MerchantTrie {
    private static final Logger log = Logger.getLogger(MerchantTrie.class.getName());
    private final TrieNode root = new TrieNode();

    public void insert(String name) {
        TrieNode node = root;
        for (char c : name.toCharArray())
            node = node.children.computeIfAbsent(c, k -> new TrieNode()); // create path
        node.isWord = true;                         // mark complete name
        log.fine(() -> "Inserted merchant " + name);
    }

    public boolean search(String name) {
        TrieNode node = walk(name);
        return node != null && node.isWord;         // full word must end here
    }

    public boolean startsWith(String prefix) {
        return walk(prefix) != null;                // path existing is enough
    }

    private TrieNode walk(String s) {
        TrieNode node = root;
        for (char c : s.toCharArray()) {
            node = node.children.get(c);
            if (node == null) return null;          // path breaks, not present
        }
        return node;
    }
}
