package com.bank.merchtrie;

import com.bank.merchtrie.trie.MerchantTrie;
import java.util.logging.Logger;

public class MerchantTrieApplication {
    private static final Logger log = Logger.getLogger(MerchantTrieApplication.class.getName());

    public static void main(String[] args) {
        MerchantTrie trie = new MerchantTrie();
        trie.insert("RELIANCE");
        trie.insert("RELIABLE");
        log.info("search RELIANCE = " + trie.search("RELIANCE"));
        log.info("search RELI = " + trie.search("RELI"));
        log.info("startsWith RELI = " + trie.startsWith("RELI"));
    }
}
